<script setup lang="ts">
import {computed,ref,watch,nextTick,onMounted} from 'vue'
import Portrait from './Portrait.vue'
type Row=Record<string,any>
const props=defineProps<{project:Row}>()
const emit=defineEmits(['generate','save'])
const selected=ref(props.project.scenes[0]?.id||''),removeOpen=ref(false),regenerateOpen=ref(false),editor=ref<HTMLElement|null>(null)
const scene=computed<Row|undefined>(()=>props.project.scenes.find((s:Row)=>s.id===selected.value)||props.project.scenes[0])
const index=computed(()=>props.project.scenes.indexOf(scene.value))
const countValid=computed(()=>Number.isInteger(props.project.sceneCount)&&props.project.sceneCount>=1&&props.project.sceneCount<=12)
const cast=computed(()=>props.project.characters.filter((c:Row)=>scene.value?.characterIds.includes(c.id)))
const locked=computed(()=>scene.value?.units?.some((u:Row)=>u.locked))
function portrait(cid:string){return props.project.annotations.find((a:Row)=>a.kind==='character'&&a.characterId===cid)}
function changed(){props.project.outlineConfirmed=false}
function choose(id:string){selected.value=id;removeOpen.value=false}
function move(direction:number){const target=props.project.scenes[index.value+direction];if(target)choose(target.id)}
function toggle(cid:string){if(!scene.value)return;const ids=scene.value.characterIds;scene.value.characterIds=ids.includes(cid)?ids.filter((id:string)=>id!==cid):[...ids,cid];changed()}
function add(){if(props.project.scenes.length>=12)return;const s={id:crypto.randomUUID().slice(0,12),title:'新场景',goal:'',connection:'',characterIds:[],units:[]};props.project.scenes.push(s);props.project.sceneCount=props.project.scenes.length;changed();choose(s.id)}
function remove(){if(!scene.value||locked.value)return;const oldIndex=index.value,id=scene.value.id;props.project.scenes=props.project.scenes.filter((s:Row)=>s.id!==id);props.project.storyboards=(props.project.storyboards||[]).filter((b:Row)=>b.sceneId!==id);if(props.project.sceneVideoApprovals)delete props.project.sceneVideoApprovals[id];props.project.sceneCount=props.project.scenes.length||1;changed();choose(props.project.scenes[Math.min(oldIndex,props.project.scenes.length-1)]?.id||'')}
function resize(target:HTMLTextAreaElement){target.style.height='auto';target.style.height=target.scrollHeight+'px'}
async function fit(){await nextTick();editor.value?.querySelectorAll('textarea').forEach(resize)}
watch(()=>[scene.value?.id,scene.value?.goal,scene.value?.connection],fit)
watch(()=>props.project.id,()=>choose(props.project.scenes[0]?.id||''))
onMounted(fit)
</script>
<template>
<section class="outline-workspace">
  <div class="outline-heading"><div><small>STORY OUTLINE</small><h2>一幕一幕，串起故事</h2><p>读清每场的目标与衔接，再选出这一幕的出场人物。</p></div><details class="outline-settings"><summary>场数与生成 <span>⌄</span></summary><div class="outline-settings-body"><label>计划场数（1–12）<input type="number" min="1" max="12" v-model.number="project.sceneCount" @input="changed"></label><p>当前已有 {{project.scenes.length}} 场；调整计划场数后，可重新生成大纲。</p><button class="primary" :disabled="!countValid||!project.characters.length" @click="regenerateOpen=true">{{project.scenes.length?'重新生成大纲':'生成故事大纲'}}</button><div v-if="regenerateOpen" class="outline-confirm"><p>按 {{project.sceneCount}} 场生成新大纲？现有大纲与分镜会被替换。</p><button class="primary" @click="regenerateOpen=false;emit('generate')">确定生成</button><button @click="regenerateOpen=false">取消</button></div></div></details></div>
  <div class="outline-layout">
    <aside class="scene-index"><div class="scene-index-heading"><h3>场景目录</h3><span>{{project.scenes.length}} 场</span></div><div class="scene-index-list" aria-label="选择场景"><button v-for="(s,i) in project.scenes" :key="s.id" :aria-pressed="scene?.id===s.id" :class="{active:scene?.id===s.id}" @click="choose(s.id)"><span class="scene-number">{{String(Number(i)+1).padStart(2,'0')}}</span><span><b>{{s.title||'未命名场景'}}</b><small>{{s.characterIds.length}} 位出场人物</small></span></button></div><button class="add-scene" :disabled="project.scenes.length>=12" @click="add">＋ 添加一场</button></aside>
    <div v-if="scene" class="scene-sheet">
      <div class="scene-sheet-heading"><span>第 {{String(index+1).padStart(2,'0')}} 幕 <i>/ {{String(project.scenes.length).padStart(2,'0')}}</i></span><span class="scene-status">{{project.outlineConfirmed?'大纲已确认':'可编辑草稿'}}</span></div>
      <div class="scene-sheet-body">
        <div ref="editor" class="scene-writing"><label class="scene-title-label">场景标题<input class="scene-title-input" v-model="scene.title" placeholder="为这一幕起一个标题" @input="changed"></label><label class="scene-text-field"><span class="field-number">01</span> 这一幕要讲什么<textarea v-model="scene.goal" rows="5" placeholder="写下本场发生的事情、冲突与故事目标……" @input="changed"/></label><label class="scene-text-field"><span class="field-number">02</span> 如何承上启下<textarea v-model="scene.connection" rows="4" placeholder="承接上一幕的什么，又为下一幕留下什么？" @input="changed"/></label><div class="scene-cast-summary"><span>本场出场</span><p>{{cast.map((c:Row)=>c.name).join(' · ')||'从右侧选择这一幕的出场人物'}}</p></div><button class="delete-scene" :disabled="locked" @click="removeOpen=!removeOpen">删除本场</button><div v-if="removeOpen" class="outline-confirm"><p>删除「{{scene.title||'未命名场景'}}」及本场剧本、分镜？保存前可重新加载已保存版本恢复。</p><button @click="remove">确定删除</button><button @click="removeOpen=false">保留本场</button></div></div>
        <aside class="scene-cast"><div class="cast-heading"><h3>谁在这一幕</h3><span>已选 {{cast.length}} 人</span></div><p>点击人物立绘，选择或取消出场。</p><div class="cast-portraits"><button v-for="c in project.characters" :key="c.id" :aria-label="c.name" :aria-pressed="scene.characterIds.includes(c.id)" :class="{chosen:scene.characterIds.includes(c.id)}" @click="toggle(c.id)"><span class="cast-check" aria-hidden="true">{{scene.characterIds.includes(c.id)?'✓':'＋'}}</span><div class="cast-image"><Portrait v-if="project.image&&portrait(c.id)" :key="c.id" :url="project.image" :box="portrait(c.id)"/><span v-else class="cast-monogram">{{c.name?.slice(0,1)||'人'}}</span></div><span class="cast-name">{{c.name}}</span></button></div><p v-if="!project.characters.length" class="cast-empty">请先添加人物档案。</p></aside>
      </div>
      <div class="scene-pagination"><button :disabled="index===0" @click="move(-1)">← 上一幕</button><span>{{index+1}} / {{project.scenes.length}}</span><button :disabled="index===project.scenes.length-1" @click="move(1)">下一幕 →</button></div>
    </div>
    <div v-else class="outline-empty"><span>序</span><h3>故事，从第一幕开始</h3><p>添加场景，自行编写；也可以在“场数与生成”中生成初稿。</p><button @click="add">＋ 添加第一幕</button></div>
  </div>
  <div v-if="project.scenes.length" class="outline-footer"><label><input type="checkbox" v-model="project.outlineConfirmed"> 确认整份大纲与人物及创作边界一致</label><button class="primary" @click="emit('save')">保存大纲</button></div>
</section>
</template>
