ading>span{font-size:10px;color:#788b6c}.scene-cast>p{font-size:10px;color:#919b84;line-height:1.9;margin:10px 0 20px}.cast-portraits{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px 8px}.cast-portraits>button{position:relative;padding:9px 4px 10px;min-width:0;border:1px solid #e3e7d9;border-radius:7px;background:#fcfcf6;transition:background .15s,border-color .15s}.cast-portraits>button:hover{border-color:#a9ba9a;background:#eff3e6}.cast-portraits>button.chosen{border-color:#739366;background:#e8efdf}.cast-image{height:83px;display:flex;align-items:center;justify-content:center;margin:2px 5px 8px;overflow:hidden}.cast-image :deep(canvas){display:block;width:100%;height:83px;object-fit:contain;background:transparent;border-radius:3px}.cast-monogram{font:30px serif;color:#a1b08f}.cast-name{font-size:10px;display:block;line-height:1.7;overflow-wrap:anywhere;color:#697c5f}.cast-check{position:absolute;right:4px;top:4px;border:1px solid #ccd6be;background:#fffef5;color:#a5b294;border-radius:50%;width:15px;height:15px;font:10px/13px sans-serif;z-index:1}.chosen .cast-check{background:#56784c;border-color:#56784c;color:white}.scene-pagination{display:flex;justify-content:space-between;align-items:center;border-top:1px solid #e5e9dc;padding:15px 25px}.scene-pagination button{background:transparent;border:0;font-size:12px;padding:8px 0}.scene-pagination button:disabled{cursor:default}.scene-pagination>span{font:11px Georgia;color:#94a084}.outline-footer{display:flex;justify-content:space-between;align-items:center;gap:18px;margin-top:20px;padding:4px 0 4px 239px}.outline-footer label{font-size:11px;color:#7e8d71}.outline-footer button{font-size:12px;white-space:nowrap}.outline-confirm{padding:12px;margin-top:10px;background:#f6eee3;border-radius:5px}.outline-confirm p{font-size:12px;line-height:1.8;margin:0 0 10px}.outline-confirm button{font-size:11px;padding:7px 10px;margin-right:6px}.outline-empty{text-align:center;padding:80px 30px;background:#fffef9;